# One superadmin, and it is the user with id 1 (generated by inline_forms).
#
# The same rule as the apps on inline_forms that came before this one
# (has_and_belongs_to_many :roles, as generated):
#
#   * superadmin? is true for user 1 holding the role "superadmin" and for
#     nobody else. Ability, controllers and views ask superadmin?, never
#     role?(:superadmin): the role on any other user is worth nothing.
#   * Giving the role to anybody else is refused with a message. A join row is
#     written as soon as `role_ids=` or `roles <<` runs on a saved user, before
#     any validation, so the refusal sits in the association callbacks of both
#     sides (the user's roles and the role's users): it raises
#     SingleSuperadmin::Refused (an ActiveRecord::RecordInvalid with the
#     message in the user's errors) before the row is written. The
#     inline_forms controller shows that message in the field.
#   * User 1 keeps the role and cannot be destroyed or soft-deleted, so the
#     app is never left without a superadmin.
#
# Who may change user 1 and who sees the role: the end of Ability.
module SingleSuperadmin
  extend ActiveSupport::Concern

  SUPERADMIN_ID = 1
  SUPERADMIN_ROLE = "superadmin"

  class Refused < ActiveRecord::RecordInvalid; end

  included do
    validate :superadmin_role_is_reserved
    validate :superadmin_is_not_soft_deleted
    before_destroy :superadmin_is_not_destroyed, prepend: true
  end

  # By name, and false without roles.
  def role?(name)
    roles.exists?(name: name.to_s)
  end

  def superadmin?
    id == SUPERADMIN_ID && role?(SUPERADMIN_ROLE)
  end

  # before_add of the user's roles and of the role's users.
  def superadmin_role_added!(role)
    return unless role.name == SUPERADMIN_ROLE && id != SUPERADMIN_ID

    refuse!(:base, :superadmin_reserved)
  end

  # before_remove of the user's roles and of the role's users.
  def superadmin_role_removed!(role)
    return unless role.name == SUPERADMIN_ROLE && id == SUPERADMIN_ID

    refuse!(:base, :superadmin_stays)
  end

  private

  def refuse!(attribute, key)
    errors.add(attribute, key)
    raise Refused, self
  end

  # A role given in memory (a new record) or found on a user other than 1 (old
  # data, a database edit): the record is not saved.
  def superadmin_role_is_reserved
    return if id == SUPERADMIN_ID

    errors.add(:base, :superadmin_reserved) if roles.any? { |role| role.name == SUPERADMIN_ROLE }
  end

  # Only for a model that includes InlineForms::SoftDeletable.
  def superadmin_is_not_soft_deleted
    errors.add(:base, :superadmin_stays) if id == SUPERADMIN_ID && try(:deleted_at).present?
  end

  def superadmin_is_not_destroyed
    return unless id == SUPERADMIN_ID

    errors.add(:base, :superadmin_stays)
    throw :abort
  end
end
